    25|// ── Types ────────────────────────────────────────────────────────────────────
    26|
    27|/**
    28| * Honest classification of an agent's real architecture.
    29| * - REAL_INDEPENDENT_AGENT: Has its own runtime process, isolated state, heartbeat
    30| * - SHARED_WORKER_WITH_ROLE: Runs on a shared worker pool with role-based routing
    31| * - UI_ONLY_LABEL: Exists only in UI/dashboard config, no runtime backing
    32| * - PLACEHOLDER: Stub with no implementation
    33| * - MOCK: Returns fake/canned data
    34| * - BROKEN: Runtime exists but crashes or fails to start
    35| * - UNKNOWN: Not yet classified
    36| */
    37|export type AgentClassification =
    38|  | 'REAL_INDEPENDENT_AGENT'
    39|  | 'SHARED_WORKER_WITH_ROLE'
    40|  | 'UI_ONLY_LABEL'
    41|  | 'PLACEHOLDER'
    42|  | 'MOCK'
    43|  | 'BROKEN'
    44|  | 'UNKNOWN';
    45|
    46|export type AgentStatus =
    47|  | 'online'
    48|  | 'offline'
    49|  | 'degraded'
    50|  | 'crashed'
    51|  | 'never_started'
    52|  | 'disabled';
    53|
    54|export type AgentRuntimeType =
