   119|const REGISTRY_DIR = path.join(process.cwd(), 'logs', 'audit', 'agent-registry');
   120|const REGISTRY_PATH = path.join(REGISTRY_DIR, 'registry.json');
   121|const REGISTRY_LOG_PATH = path.join(REGISTRY_DIR, 'events.jsonl');
   122|
   123|let inMemoryRegistry: Map<string, AgentRegistryRecord> | null = null;
   124|
   125|/**
   126| * Load the registry from durable storage (or in-memory cache).
   127| */
   128|export async function loadAgentRegistry(): Promise<Map<string, AgentRegistryRecord>> {
   129|  if (inMemoryRegistry) return inMemoryRegistry;
   130|
   131|  const registry = new Map<string, AgentRegistryRecord>();
   132|
   133|  try {
   134|    let raw: string;
   135|    if (isDurableStoreConfigured()) {
   136|      const data = await readDurableJson<AgentRegistryRecord[]>(REGISTRY_PATH, []);
   137|      raw = JSON.stringify(data);
   138|    } else {
   139|      raw = await readFile(REGISTRY_PATH, 'utf8');
   140|    }
   141|    const records: AgentRegistryRecord[] = JSON.parse(raw);
   142|    for (const record of records) {
   143|      if (record && typeof record.agent_id === 'string') {
   144|        registry.set(record.agent_id, record);
   145|      }
   146|    }
   147|  } catch {
   148|    // File doesn't exist yet — start with empty registry
   149|  }
   150|
   151|  inMemoryRegistry = registry;
   152|  return registry;
   153|}
   154|
   155|/**
   156| * Persist the registry to durable storage.
   157| */
   158|async function persistAgentRegistry(registry: Map<string, AgentRegistryRecord>): Promise<void> {
   159|  const records = Array.from(registry.values());
   160|
   161|  if (isDurableStoreConfigured()) {
   162|    await writeDurableJson(REGISTRY_PATH, records);
   163|  } else {
   164|    await mkdir(REGISTRY_DIR, { recursive: true });
   165|    const tmp = path.join(REGISTRY_DIR, 'registry.json.tmp');
   166|    await writeFile(tmp, JSON.stringify(records, null, 2), 'utf8');
   167|    await rename(tmp, REGISTRY_PATH);
   168|  }
   169|}
   170|
   171|/**
   172| * Append a registry event to the append-only log.
   173| */
   174|async function appendRegistryEvent(event: Record<string, unknown>): Promise<void> {
   175|  try {
   176|    const entry = JSON.stringify({ ...event, at: new Date().toISOString() });
   177|    if (isDurableStoreConfigured()) {
   178|      await appendDurableEvent(REGISTRY_LOG_PATH, event);
   179|    } else {
   180|      await mkdir(REGISTRY_DIR, { recursive: true });
   181|      await appendFile(REGISTRY_LOG_PATH, `${entry}\n`, 'utf8');
   182|    }
   183|  } catch {
   184|    // best-effort
   185|  }
   186|}
   187|
   188|// ── Registry Operations ──────────────────────────────────────────────────────
   189|
   190|/**
   191| * Get a single agent record by ID.
   192| */
   193|export async function getAgentRecord(agentId: string): Promise<AgentRegistryRecord | null> {
   194|  const registry = await loadAgentRegistry();
   195|  return registry.get(agentId) ?? null;
   196|}
   197|
   198|/**
   199| * Get all agent records.
   200| */
   201|export async function listAgentRecords(): Promise<AgentRegistryRecord[]> {
   202|  const registry = await loadAgentRegistry();
   203|  return Array.from(registry.values()).sort((a, b) => a.agent_id.localeCompare(b.agent_id));
   204|}
   205|
   206|/**
   207| * Update a single agent record. Returns the updated record or null if not found.
   208| */
   209|export async function updateAgentRecord(
   210|  agentId: string,
   211|  updates: Partial<AgentRegistryRecord>,
   212|): Promise<AgentRegistryRecord | null> {
   213|  const registry = await loadAgentRegistry();
   214|  const existing = registry.get(agentId);
   215|  if (!existing) return null;
   216|
   217|  const updated: AgentRegistryRecord = {
   218|    ...existing,
   219|    ...updates,
   220|    agent_id: existing.agent_id, // immutable
   221|    updated_at: new Date().toISOString(),
   222|  };
   223|
   224|  registry.set(agentId, updated);
   225|  await persistAgentRegistry(registry);
   226|  await appendRegistryEvent({
   227|    type: 'record_updated',
   228|    agent_id: agentId,
   229|    fields: Object.keys(updates),
   230|  });
   231|
   232|  return updated;
   233|}
   234|
   235|/**
   236| * Record a heartbeat for an agent.
   237| */
   238|export async function recordAgentHeartbeat(agentId: string): Promise<AgentRegistryRecord | null> {
